let curLang='it', curYear=false;
function setBilling(year){ curYear=year;
  document.querySelectorAll('.plan').forEach(plan=>{
    const pr=plan.querySelector('.price'); if(!pr) return;
    const d=pr.dataset, amt=pr.querySelector('.amount'), was=pr.querySelector('.was'), note=plan.querySelector('[data-billnote]');
    if(year){
      if(amt) amt.textContent=d.y;
      if(was){ was.textContent='€'+d.m; was.hidden=false; }
      if(note){ note.classList.add('year'); note.textContent=LANG[curLang]['bill.year_tpl'].replace('{tot}','€'+d.ytot).replace('{save}','€'+d.save); }
    } else {
      if(amt) amt.textContent=d.m;
      if(was) was.hidden=true;
      if(note){ note.classList.remove('year'); note.textContent=LANG[curLang]['bill.note_m']; }
    }
  });
}
function applyLang(l){ if(!LANG[l]) l='it'; curLang=l;
  try{localStorage.setItem('lf_land_lang',l);}catch(e){}
  document.documentElement.lang=l;
  document.querySelectorAll('[data-i18n]').forEach(el=>{ const v=LANG[l][el.dataset.i18n]; if(v!=null) el.textContent=v; });
  document.querySelectorAll('[data-i18n-html]').forEach(el=>{ const v=LANG[l][el.dataset.i18nHtml]; if(v!=null) el.innerHTML=v; });
  document.querySelectorAll('[data-lang-select]').forEach(s=>{ if(s.value!==l) s.value=l; });
  const mm=(LANG[l]['mock.months']||'').split(','); document.querySelectorAll('#da-chart .da-col span').forEach((c,i)=>{ if(mm[i]!=null) c.textContent=mm[i]; });
  setBilling(curYear);
}
document.querySelectorAll('[data-lang-select]').forEach(s=>s.addEventListener('change',()=>applyLang(s.value)));
const bill=document.getElementById('billing');
bill.addEventListener('click',e=>{ const b=e.target.closest('[data-bill]'); if(!b) return;
  bill.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b)); setBilling(b.dataset.bill==='year'); });
document.getElementById('year').textContent=new Date().getFullYear();
const nav=document.getElementById('nav');
addEventListener('scroll',()=>nav.classList.toggle('scrolled',scrollY>10),{passive:true});
// micro-animazioni allo scroll
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(reduce){ document.querySelectorAll('.reveal,.stagger').forEach(el=>el.classList.add('in')); }
else{ const io=new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } }),{threshold:.12,rootMargin:'0px 0px -8% 0px'});
  document.querySelectorAll('.reveal,.stagger').forEach(el=>io.observe(el)); }
if('serviceWorker' in navigator){ addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{})); }
(function(){ let l='it'; try{ l=localStorage.getItem('lf_land_lang')||((navigator.language||'it').toLowerCase().startsWith('it')?'it':'en'); }catch(e){} applyLang(l); })();
